(function(){
'use strict';

class CPM831Adapter extends USF.SimulationAdapter {
    constructor(){
        super();
        this.name = 'Edificio Quindio CPM and Fast-Tracking';
        this.version = '1.1.0';

        this.OPTIONS = {
            A:{cat:'crash',  daysSaved:10, directM:240, reworkM:0,  riskAdd:1, label:'A. Crash structural concrete'},
            B:{cat:'crash',  daysSaved:7,  directM:180, reworkM:0,  riskAdd:1, label:'B. Crash MEP rough-in'},
            C:{cat:'crash',  daysSaved:12, directM:280, reworkM:0,  riskAdd:1, label:'C. Crash finishes (dual crews)'},
            D:{cat:'fasttrack', daysSaved:10, directM:0,  reworkM:120, riskAdd:2, label:'D. Fast-track structure to envelope'},
            E:{cat:'fasttrack', daysSaved:14, directM:0,  reworkM:190, riskAdd:4, label:'E. Fast-track wet finishes (high-risk)'},
            F:{cat:'fasttrack', daysSaved:5,  directM:0,  reworkM:50,  riskAdd:1, label:'F. Fast-track foundation to structure'},
            G:{cat:'crash',  daysSaved:7,  directM:90,  reworkM:0,  riskAdd:1, label:'G. Pre-fab window units'},
            H:{cat:'crash',  daysSaved:7,  directM:200, reworkM:0,  riskAdd:1, label:'H. Weekend shifts on structure'},
            X:{cat:'bad',    daysSaved:0,  directM:130, reworkM:0,  riskAdd:1, label:'X. Crash a non-critical activity (waste)'}
        };

        this.ROUNDS = [
            {
                period:1,
                title:`Round 1 — Baseline diagnosis: WBS, CPM and the float you actually have`,
                description:`<p><strong>Constructora Andina Sanin S.A.S.</strong> — Bogota. The <em>Edificio Quindio</em> project: 6 storeys, 48 apartments, contract value COP 14,200M, baselined at <strong>38 weeks / 142 activities / 4 phases</strong> (Foundation, Structure, Envelope and MEP, Finishes).</p><p>You have the printed Gantt and the activity list with durations, predecessors and lags. <strong>Your job in 15 minutes:</strong> validate the WBS, run the forward and backward pass, identify the critical path, find the near-critical chains, and check for two activities that are mis-coded into the wrong phase.</p><p><em>The owner email and the Week-12 progress report are still in the facilitator envelope. Do not open them yet — first you plan the baseline like a Round-1 planner, not a Round-2 firefighter.</em></p>`
            },
            {
                period:2,
                title:`Round 2 — Week-12 reality: SPI 0.84, CPI 0.96, and a slip you did not log`,
                description:`<p>The owner of <em>Edificio Quindio</em> just emailed: <em>"buyer for the entire 4th floor wants to move in by November — substantial completion at week 32, not 38. Tell me by Friday if we can do it and what it costs."</em></p><p>Then the Week-12 progress report drops: <strong>SPI 0.84, CPI 0.96, BCWS 5,180M, BCWP 4,350M, ACWP 4,530M.</strong> Structural concrete on floors 2 and 3 is <strong>8 days behind plan</strong> after a rebar-supplier short-delivery in Week 9. The 8-day slip has eaten the entire 9-day float on the near-critical chain.</p><p>Compute the EAC at current CPI. Decide which chain is now critical. Decide whether to flag the slip to the owner separately or fold it into the acceleration plan. And the formwork sub just called — they will pull the crew on Friday unless you commit extra work now.</p>`
            },
            {
                period:3,
                title:`Round 3 — Compression menu: rank options by cost-per-week-saved`,
                description:`<p>You have a menu of compression options. Each is either <strong>fast-tracking</strong> (overlap previously sequential activities — no direct cost but rework risk) or <strong>crashing</strong> (add resources or overtime — direct cost but lower risk).</p><p>Pick a target completion week and a mix of options. The team has to weigh:</p><ul><li><strong>Cost per week saved</strong> — crashing rule of thumb is 3-5% of project cost (COP 425-710M / week here)</li><li><strong>Rework risk premium</strong> — aggressive fast-tracking carries 15-20% expected rework cost on overlapped work</li><li><strong>Bank covenant</strong> — front-loaded compression that pushes monthly cash burn 25% above baseline trips the construction loan</li><li><strong>Float migration</strong> — after each compression decision, the critical path can shift to a new chain</li></ul><p>One option in the menu is a trap. Spotting it is part of the round.</p>`
            },
            {
                period:4,
                title:`Round 4 — Friday: go / counter-offer / decline`,
                description:`<p>You are presenting to a steering committee in two hours. The deliverable: <strong>recommendation, compressed CPM, S-curve, risk register, cost number</strong>.</p><p>The owner has dangled <strong>COP 180M bonus at week 32 only — zero at week 33+</strong>. The <strong>penalty clause is COP 35M / week beyond week 38</strong>. The 32-week date is <em>not</em> in the contract — accepting it creates a brand-new exposure.</p><p>Three contractual levers are open: <strong>penalty re-pricing</strong> (defer the start, force-majeure carve-out for the rebar slip), <strong>bonus re-shaping</strong> (pro-rate so week 33-34 still pays something), and <strong>the bank conversation</strong> (a pre-emptive call about covenant relief versus reactive damage control).</p><p>The committee will ask three questions: what if the wet-trades overlap goes wrong? where does your S-curve break the bank covenant? and how much do I save if I give you 2 more weeks?</p>`
            }
        ];
    }

    initialize(state){
        if(!state.domainState || Object.keys(state.domainState).length === 0){
            state.domainState = {
                forecastDuration: 38,
                ownerTrust: 50,
                riskScore: 0,
                extraCostM: 0,
                bonusM: 0,
                penaltyM: 0,
                netM: 0,
                bankCovenantBreach: false,
                roundScore: 0,
                cumulativeScore: 0,
                hasDisclosed: false,
                committedFormwork: false,
                targetWeek: 38,
                weeksSaved: 0,
                durationHistory: [],
                trustHistory: [],
                extraCostHistory: [],
                netHistory: [],
                roundScoreHistory: []
            };
        }
        if(!state.decisions || Object.keys(state.decisions).length === 0){
            state.decisions = {};
        }
        var self = this;
        setTimeout(function(){
            self._updateBriefing(state);
            self._attachOptionListeners();
        }, 0);
    }

    validateDecisions(decisions){
        var period = window.mySimulation.state.currentPeriod;
        if(period === 1){
            decisions.cpDuration   = parseInt(document.getElementById('cpDurationInput').value, 10);
            decisions.floatAvg     = parseInt(document.getElementById('floatAvgInput').value, 10);
            decisions.wbsErrors    = parseInt(document.getElementById('wbsErrorsInput').value, 10);
            decisions.nearCritical = parseInt(document.getElementById('nearCriticalInput').value, 10);
            if(isNaN(decisions.cpDuration) || isNaN(decisions.floatAvg) ||
               isNaN(decisions.wbsErrors)  || isNaN(decisions.nearCritical)){
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_r1'), 'warning');
                return false;
            }
        } else if(period === 2){
            decisions.evmEac    = parseInt(document.getElementById('evmEacInput').value, 10);
            decisions.newCp     = document.getElementById('newCpInput').value;
            decisions.disclose  = document.getElementById('discloseInput').value;
            decisions.formwork  = document.getElementById('formworkInput').value;
            if(!decisions.newCp || !decisions.disclose || !decisions.formwork || isNaN(decisions.evmEac)){
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_r2'), 'warning');
                return false;
            }
        } else if(period === 3){
            var t = document.getElementById('targetWeekInput').value;
            if(!t){
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_r3_target'), 'warning');
                return false;
            }
            decisions.targetWeek = parseInt(t, 10);
            var picks = [];
            var checks = document.querySelectorAll('input[name="compOpt"]:checked');
            for(var i = 0; i < checks.length; i++){
                picks.push(checks[i].value);
            }
            decisions.options = picks;
        } else if(period === 4){
            decisions.recommendation = document.getElementById('recommendationInput').value;
            decisions.penalty        = document.getElementById('penaltyInput').value;
            decisions.bonus          = document.getElementById('bonusInput').value;
            decisions.bank           = document.getElementById('bankInput').value;
            if(!decisions.recommendation || !decisions.penalty || !decisions.bonus || !decisions.bank){
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_r4'), 'warning');
                return false;
            }
        }
        return true;
    }

    calculateResults(state){
        var period = state.currentPeriod;
        var d = state.decisions;
        var ds = state.domainState;
        var feedback = '';
        var roundScore = 0;
        var trustDelta = 0;
        var riskDelta  = 0;

        if(period === 1){
            var cpAcc      = this._scoreClose(d.cpDuration, 38, 1, 3);
            var floatAcc   = this._scoreClose(d.floatAvg, 9, 1, 3);
            var wbsAcc     = (d.wbsErrors === 2) ? 25 : (d.wbsErrors === 1 || d.wbsErrors === 3) ? 10 : 0;
            var nearAcc    = (d.nearCritical === 2) ? 25 : (d.nearCritical === 1 || d.nearCritical === 3) ? 10 : 0;
            roundScore = Math.min(100, cpAcc + floatAcc + wbsAcc + nearAcc);
            trustDelta = (cpAcc >= 20 && floatAcc >= 20) ? 6 : 0;
            feedback  = '<h3>Round 1 — Baseline accuracy</h3>';
            feedback += '<p><strong>Critical-path duration:</strong> your answer ' + d.cpDuration + ' wk vs baseline 38 wk. Score ' + cpAcc + '/25.</p>';
            feedback += '<p><strong>Average float on non-critical chains:</strong> your answer ' + d.floatAvg + ' d vs baseline 9 d. Score ' + floatAcc + '/25.</p>';
            feedback += '<p><strong>WBS coding errors found:</strong> ' + d.wbsErrors + ' (target: 2). Score ' + wbsAcc + '/25.</p>';
            feedback += '<p><strong>Near-critical chains identified:</strong> ' + d.nearCritical + ' (target: 2 chains, 5 days or less of float). Score ' + nearAcc + '/25.</p>';
            feedback += '<p><em>Why this matters:</em> only critical-path activities respond to crashing money. Spending money to compress activities that have float is the most common rookie error — and the diagnosis you do now decides which options in Round 3 are even worth pricing.</p>';
        }

        else if(period === 2){
            var eacAcc = this._scoreClose(d.evmEac, 14790, 50, 250);
            var newCpAcc = (d.newCp === 'wet') ? 25 : (d.newCp === 'mep') ? 10 : 0;
            var discloseAcc = 0;
            if(d.disclose === 'separate'){ discloseAcc = 25; trustDelta += 12; ds.hasDisclosed = true; }
            else if(d.disclose === 'folded'){ discloseAcc = 8; trustDelta -= 6; }
            else { discloseAcc = 0; trustDelta -= 18; }
            var formAcc = 0;
            if(d.formwork === 'commit'){ formAcc = 18; ds.committedFormwork = true; riskDelta += 1; }
            else if(d.formwork === 'negotiate'){ formAcc = 22; }
            else { formAcc = 6; riskDelta += 2; }
            roundScore = Math.min(100, eacAcc + newCpAcc + discloseAcc + formAcc);
            feedback  = '<h3>Round 2 — Variance shock</h3>';
            feedback += '<p><strong>Schedule Variance:</strong> SV = BCWP - BCWS = 4,350 - 5,180 = <strong>-COP 830M</strong> (behind schedule).</p>';
            feedback += '<p><strong>Cost Variance:</strong> CV = BCWP - ACWP = 4,350 - 4,530 = <strong>-COP 180M</strong> (over budget).</p>';
            feedback += '<p><strong>EAC at current CPI:</strong> EAC = BAC / CPI = 14,200 / 0.96 = <strong>~COP 14,790M</strong> (about 4% over budget at completion). Your answer was COP ' + d.evmEac + 'M — score ' + eacAcc + '/25.</p>';
            feedback += '<p><strong>New critical chain:</strong> wet finishes — envelope was always tight behind structure, so when structure slipped, the wet finishes chain inherited critical-path status. Score ' + newCpAcc + '/25.</p>';
            feedback += '<p><strong>Disclosure choice:</strong> ' + this._discloseLabel(d.disclose) + ' — score ' + discloseAcc + '/25. The owner CFO will pull the SPI from your status report on Sunday night. Disclose now and you are the contractor who flags problems early. Disclose under cross-examination and you are the contractor who hid them.</p>';
            feedback += '<p><strong>Formwork crew:</strong> ' + this._formworkLabel(d.formwork) + ' — score ' + formAcc + '/25.</p>';
        }

        else if(period === 3){
            ds.targetWeek = d.targetWeek;
            var picks = d.options || [];
            var totalDays = 0, directM = 0, reworkM = 0, riskAdd = 0;
            var hasWaste = false, hasFTHigh = false;
            for(var i = 0; i < picks.length; i++){
                var k = picks[i];
                var o = this.OPTIONS[k];
                if(!o) continue;
                if(o.cat === 'bad'){ hasWaste = true; }
                if(k === 'E'){ hasFTHigh = true; }
                totalDays += o.daysSaved;
                directM   += o.directM;
                reworkM   += o.reworkM;
                riskAdd   += o.riskAdd;
            }
            var weeksSaved = totalDays / 7;
            ds.weeksSaved = weeksSaved;
            ds.forecastDuration = Math.max(20, 38 + 8/7 - weeksSaved);
            ds.forecastDuration = Math.round(ds.forecastDuration * 10) / 10;
            ds.extraCostM = directM + reworkM;
            riskDelta += riskAdd;
            ds.riskScore += riskAdd;

            var actualWeek = ds.forecastDuration;
            ds.bonusM = (actualWeek <= 32.0) ? 180 : (actualWeek <= 33.5 ? 90 : 0);
            ds.penaltyM = (actualWeek > 38.0) ? Math.ceil(actualWeek - 38) * 35 : 0;
            ds.netM = ds.bonusM - ds.penaltyM - directM - reworkM;

            var bankBreach = (directM + reworkM > 600) || (weeksSaved >= 4 && (directM + reworkM) > 350);
            ds.bankCovenantBreach = bankBreach;

            var hitTarget = (actualWeek <= d.targetWeek + 0.3);

            var targetPick = 0;
            if(d.targetWeek === 32) targetPick = 18;
            else if(d.targetWeek === 33) targetPick = 22;
            else if(d.targetWeek === 34) targetPick = 25;
            else if(d.targetWeek === 35) targetPick = 18;
            else targetPick = 12;
            var hitBonus = hitTarget ? 22 : 6;
            var efficiencyPenalty = hasWaste ? 14 : 0;
            var ftHighPenalty = hasFTHigh ? 8 : 0;
            var costEff = 0;
            if(weeksSaved > 0){
                var copPerWeek = (directM + reworkM) / Math.max(weeksSaved, 0.1);
                if(copPerWeek <= 200) costEff = 25;
                else if(copPerWeek <= 350) costEff = 18;
                else if(copPerWeek <= 500) costEff = 10;
                else costEff = 4;
            } else { costEff = (d.targetWeek === 38) ? 14 : 2; }
            var bankPen = bankBreach ? 8 : 0;

            roundScore = Math.max(0, Math.min(100, targetPick + hitBonus + costEff - efficiencyPenalty - ftHighPenalty - bankPen + 25));
            trustDelta += hitTarget ? 6 : -6;
            if(hasWaste) trustDelta -= 4;
            if(bankBreach) trustDelta -= 6;

            feedback  = '<h3>Round 3 — Compression mix</h3>';
            feedback += '<p><strong>Target completion:</strong> week ' + d.targetWeek + '. <strong>Forecast after compression:</strong> week ' + ds.forecastDuration.toFixed(1) + '.</p>';
            feedback += '<p><strong>Days saved:</strong> ' + totalDays + ' d (' + weeksSaved.toFixed(1) + ' wk). <strong>Direct crash cost:</strong> COP ' + directM + 'M. <strong>Expected rework:</strong> COP ' + reworkM + 'M. <strong>Total acceleration spend:</strong> COP ' + (directM + reworkM) + 'M.</p>';
            feedback += '<table><tr><th>Outcome</th><th>Value</th></tr>';
            feedback += '<tr><td>Bonus earned (180M at week 32, 90M at week 33-33.5)</td><td>COP ' + ds.bonusM + 'M</td></tr>';
            feedback += '<tr><td>Penalty exposure beyond week 38</td><td>COP ' + ds.penaltyM + 'M</td></tr>';
            feedback += '<tr><td>Acceleration spend</td><td>COP ' + (directM + reworkM) + 'M</td></tr>';
            feedback += '<tr><td><strong>Net P&amp;L impact this round</strong></td><td><strong>COP ' + ds.netM + 'M</strong></td></tr>';
            feedback += '<tr><td>Bank covenant on cash-burn</td><td>' + (bankBreach ? '<strong>BREACH FORECAST</strong> (+25% over baseline)' : 'Within tolerance') + '</td></tr>';
            feedback += '</table>';
            if(hasWaste){
                feedback += '<p><strong>Wasted spend detected:</strong> Option X crashes a non-critical activity. You spent COP 130M for zero days saved on the critical path. Float is a free resource — spending money to compress it is the rookie error this simulation tests for.</p>';
            }
            if(hasFTHigh){
                feedback += '<p><strong>Aggressive overlap warning:</strong> Option E (wet finishes onto unsigned-off structure) carries 18% expected rework probability. Risk-weighted, fast-tracking is rarely free above ~10% schedule compression.</p>';
            }
            if(bankBreach){
                feedback += '<p><strong>Bank covenant alert:</strong> Schedule compression has a cash-flow shadow. Front-loading work front-loads cash needs. The construction loan covenant trips at +25% over baseline monthly draw.</p>';
            }
            feedback += '<p><em>After every compression decision, the critical path can migrate. The discipline that distinguishes a planner who knows MS Project from one who knows project management is the rerun of the forward-and-backward pass after each move.</em></p>';
        }

        else if(period === 4){
            var alignmentScore = 0;
            var rec = d.recommendation;
            var aggressive = (ds.targetWeek <= 33);
            var moderate   = (ds.targetWeek === 34 || ds.targetWeek === 35);
            var defensive  = (ds.targetWeek >= 38);

            if(rec === 'go' && aggressive && ds.bonusM >= 90 && !ds.bankCovenantBreach){ alignmentScore = 22; trustDelta += 6; }
            else if(rec === 'counter' && (moderate || (aggressive && ds.bonusM === 0))){ alignmentScore = 26; trustDelta += 8; }
            else if(rec === 'decline' && defensive){ alignmentScore = 22; trustDelta += 4; }
            else if(rec === 'go' && ds.netM < 0){ alignmentScore = 6; trustDelta -= 8; }
            else { alignmentScore = 12; }

            var penScore = 0;
            if(d.penalty === 'renegotiate' && (rec === 'go' || rec === 'counter')){ penScore = 22; trustDelta += 4; }
            else if(d.penalty === 'renegotiate'){ penScore = 14; }
            else if(d.penalty === 'accept'  && rec === 'decline'){ penScore = 14; }
            else if(d.penalty === 'accept'  && (rec === 'go' || rec === 'counter')){ penScore = 6; trustDelta -= 4; }
            else { penScore = 2; trustDelta -= 4; }

            var bonScore = 0;
            if(d.bonus === 'prorated' && (rec === 'counter' || rec === 'go')){ bonScore = 22; }
            else if(d.bonus === 'prorated'){ bonScore = 14; }
            else if(d.bonus === 'keep' && rec === 'go'){ bonScore = 14; }
            else if(d.bonus === 'drop' && rec === 'decline'){ bonScore = 16; }
            else { bonScore = 6; }

            var bankScore = 0;
            if(d.bank === 'proactive' && (ds.bankCovenantBreach || aggressive)){ bankScore = 22; trustDelta += 3; }
            else if(d.bank === 'proactive'){ bankScore = 16; }
            else if(d.bank === 'reactive'){ bankScore = 8; }
            else { bankScore = 2; trustDelta -= 5; if(ds.bankCovenantBreach) trustDelta -= 5; }

            roundScore = Math.min(100, alignmentScore + penScore + bonScore + bankScore + 8);

            feedback  = '<h3>Round 4 — Friday recommendation</h3>';
            feedback += '<p><strong>Recommendation:</strong> ' + this._recLabel(rec) + ' (target was week ' + ds.targetWeek + ', forecast ' + ds.forecastDuration.toFixed(1) + ') — alignment score ' + alignmentScore + '/25.</p>';
            feedback += '<p><strong>Penalty re-pricing:</strong> ' + this._penLabel(d.penalty) + ' — score ' + penScore + '/25.</p>';
            feedback += '<p><strong>Bonus structure:</strong> ' + this._bonLabel(d.bonus) + ' — score ' + bonScore + '/25.</p>';
            feedback += '<p><strong>Bank conversation:</strong> ' + this._bankLabel(d.bank) + ' — score ' + bankScore + '/25.</p>';
            feedback += '<p><strong>Final P&amp;L position:</strong> bonus COP ' + ds.bonusM + 'M, penalty COP ' + ds.penaltyM + 'M, acceleration spend COP ' + Math.round(ds.extraCostM) + 'M — net COP ' + ds.netM + 'M. Owner trust ' + Math.max(0, Math.min(100, ds.ownerTrust + trustDelta)) + '/100.</p>';
            if(rec === 'go' && d.penalty !== 'renegotiate'){
                feedback += '<p><strong>Asymmetric trap:</strong> you just signed up for a COP 35M/week penalty against a date that did not exist 4 days ago, in exchange for a bonus that requires aggressive compression which itself raises the probability of missing. Counter-offers exist for a reason.</p>';
            }
            if(rec === 'decline' && ds.targetWeek <= 33){
                feedback += '<p><strong>Inconsistency:</strong> Round 3 picked an aggressive target, Round 4 declined. The committee will ask why you priced the compression if you were not going to commit. Consistent posture matters as much as the numbers.</p>';
            }
            feedback += '<p><em>The right answer in real life is rarely a clean yes or no. It is yes-if and no-because. The contractual levers are the language of yes-if.</em></p>';
        }

        ds.ownerTrust  = Math.max(0, Math.min(100, ds.ownerTrust + trustDelta));
        ds.roundScore  = roundScore;
        ds.cumulativeScore += roundScore;

        ds.durationHistory.push(period === 1 ? 38 : ds.forecastDuration);
        ds.trustHistory.push(ds.ownerTrust);
        ds.extraCostHistory.push(Math.round(ds.extraCostM));
        ds.netHistory.push(ds.netM);
        ds.roundScoreHistory.push(roundScore);

        // Persist the running average score into domainState for the grading/reporting
        // layer (results_utils.php reads domainState.performance.overallScore -> score).
        var _sc = this._avg(ds);
        ds.score = _sc;
        ds.performance = { overallScore: _sc, grade: this._grade(_sc) };

        var fbEl = document.getElementById('feedbackPanel');
        if(fbEl){
            fbEl.innerHTML = feedback;
            fbEl.classList.add('active');
        }

        var self = this;
        setTimeout(function(){
            self._updateBriefing({currentPeriod: state.currentPeriod + 1});
            self._attachOptionListeners();
        }, 500);

        return {
            period: period,
            forecastDuration: ds.forecastDuration,
            extraCostM: Math.round(ds.extraCostM),
            netM: ds.netM,
            ownerTrust: ds.ownerTrust,
            riskScore: ds.riskScore,
            roundScore: roundScore,
            score: _sc,
            overallScore: _sc
        };
    }

