                    { label: 'Forecast', data: ds.durationHistory, borderColor: '#f08a2c', backgroundColor: 'rgba(240,138,44,0.18)', borderWidth: 3, fill: true, tension: 0.18 },
                    { label: 'Baseline (38)', data: baseline, borderColor: '#1f3a5f', borderWidth: 2, borderDash: [6, 4], fill: false, pointRadius: 0 },
