    _avg(ds){
        var h = ds.roundScoreHistory || [];
        return h.length ? Math.round(h.reduce(function(a, b){ return a + b; }, 0) / h.length) : 0;
    }

    _grade(score){
        if(score >= 75) return 'Senior PM ready for owner CFO';
        if(score >= 60) return 'Solid recovery planner';
        if(score >= 45) return 'Diagnoses well, defends weakly';
        return 'Junior planner';
    }

    getPerformanceSummary(history){
        if(!history.length) return {};
        var ds = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
        var totalScore = (ds.roundScoreHistory || []).reduce(function(a, b){ return a + b; }, 0);
        var avgScore = Math.round(totalScore / Math.max((ds.roundScoreHistory || []).length, 1));
        var t = function(k){ return window.mySimulation.t(k); };
        var ratingKey = 'rate_junior';
        if(avgScore >= 75) ratingKey = 'rate_senior';
        else if(avgScore >= 60) ratingKey = 'rate_solid';
        else if(avgScore >= 45) ratingKey = 'rate_diag';
        var rating = t(ratingKey);

        var insights = [];
        if(ds.hasDisclosed) insights.push(t('ins_disclosed'));
        else insights.push(t('ins_not_disclosed'));
        if(ds.bankCovenantBreach) insights.push(t('ins_bank'));
        if(ds.netM > 100) insights.push(t('ins_net_pos'));
        else if(ds.netM < -100) insights.push(t('ins_net_neg'));
        else insights.push(t('ins_net_even'));
        if(ds.ownerTrust >= 75) insights.push(t('ins_trust_high'));
        else if(ds.ownerTrust < 40) insights.push(t('ins_trust_low'));

        return {
            averageScore: avgScore,
            overallScore: avgScore,
            totalPeriods: history.length,
            totalScore: totalScore,
            ownerTrust: ds.ownerTrust || 0,
            netM: ds.netM || 0,
            rating: rating,
            insights: insights
        };
    }

    getHint(state, results){
        var ds = state.domainState;
        if(state.currentPeriod === 1 && results && results.roundScore < 40) return window.mySimulation.t('hint_r1_weak');
        if(state.currentPeriod === 2 && !ds.hasDisclosed) return window.mySimulation.t('hint_r2_disclose');
        if(state.currentPeriod === 3 && ds.bankCovenantBreach) return window.mySimulation.t('hint_r3_bank');
        if(state.currentPeriod === 3 && ds.weeksSaved < 1 && ds.targetWeek <= 35) return window.mySimulation.t('hint_r3_short');
        return null;
    }

