    _updateBriefing(state){
        var period = Math.min(state.currentPeriod || 1, this.ROUNDS.length);
        var round = this.ROUNDS[period - 1];
        var briefEl = document.getElementById('briefingText');
        if(briefEl) briefEl.innerHTML = round.description;
        var titleEl = document.getElementById('phaseTitle');
        if(titleEl) titleEl.textContent = round.title;
        var fbEl = document.getElementById('feedbackPanel');
        if(fbEl && state.currentPeriod === 1){ fbEl.classList.remove('active'); fbEl.innerHTML = ''; }
        for(var i = 1; i <= 4; i++){
            var g = document.getElementById('r' + i + 'Group');
            if(g) g.style.display = (i === period) ? 'block' : 'none';
        }
    }

    _attachOptionListeners(){
        var self = this;
        var checks = document.querySelectorAll('input[name="compOpt"]');
        for(var i = 0; i < checks.length; i++){
            checks[i].onchange = function(){ self._updateR3Preview(); };
        }
        var t = document.getElementById('targetWeekInput');
        if(t) t.onchange = function(){ self._updateR3Preview(); };
    }

    _updateR3Preview(){
        var checks = document.querySelectorAll('input[name="compOpt"]:checked');
        var totalDays = 0, directM = 0, reworkM = 0;
        for(var i = 0; i < checks.length; i++){
            var o = this.OPTIONS[checks[i].value];
            if(!o) continue;
            totalDays += o.daysSaved;
            directM   += o.directM;
            reworkM   += o.reworkM;
        }
        var weeksSaved = totalDays / 7;
        var forecast = Math.max(20, 38 + 8/7 - weeksSaved);
        var t = document.getElementById('targetWeekInput');
        var target = t ? t.value : '';
        var preview = document.getElementById('r3Preview');
        if(!preview) return;
        if(checks.length === 0 && !target){
            preview.classList.remove('active');
            preview.innerHTML = '';
            return;
        }
        var copPerWeek = weeksSaved > 0 ? Math.round((directM + reworkM) / weeksSaved) : 0;
        var html = '<strong>Live preview</strong><br>';
        html += 'Days saved: ' + totalDays + ' d (' + weeksSaved.toFixed(1) + ' wk) — Forecast: <strong>week ' + forecast.toFixed(1) + '</strong><br>';
        html += 'Direct cost: COP ' + directM + 'M | Expected rework: COP ' + reworkM + 'M | Total: <strong>COP ' + (directM + reworkM) + 'M</strong>';
        if(weeksSaved > 0) html += ' | Cost per week saved: COP ' + copPerWeek + 'M';
        if(target) html += '<br>Target: week ' + target + (forecast <= parseFloat(target) + 0.3 ? ' — ON TARGET' : ' — SHORT BY ' + (forecast - parseFloat(target)).toFixed(1) + ' wk');
        preview.innerHTML = html;
        preview.classList.add('active');
    }

    _scoreClose(answer, target, exactBand, closeBand){
        var d = Math.abs(answer - target);
        if(d <= exactBand) return 25;
        if(d <= closeBand) return 14;
        if(d <= closeBand * 2) return 6;
        return 0;
    }

    _discloseLabel(v){
        if(v === 'separate') return 'Disclosed separately — credibility preserved';
        if(v === 'folded')   return 'Folded into acceleration — partial disclosure';
        return 'Did not disclose — owner CFO will catch the SPI';
    }
    _formworkLabel(v){
        if(v === 'commit')    return 'Committed — crew retained, sub costs locked';
        if(v === 'negotiate') return 'Negotiated retention bonus — flexibility preserved';
        return 'Released — new crew sourcing risk in the middle of compression';
    }
    _recLabel(v){
        if(v === 'go')      return 'Go — accept week 32';
        if(v === 'counter') return 'Counter-offer week 33 or 34';
        return 'Decline — hold week 38';
    }
    _penLabel(v){
        if(v === 'renegotiate') return 'Renegotiate — defer start, force majeure carve-out';
        if(v === 'accept')      return 'Accept current penalty against new date';
        return 'Did not raise penalty';
    }
    _bonLabel(v){
        if(v === 'prorated') return 'Pro-rated bonus structure';
        if(v === 'keep')     return 'Kept the binary bonus';
        return 'Dropped the bonus';
    }
    _bankLabel(v){
        if(v === 'proactive') return 'Pre-emptive bank call';
        if(v === 'reactive')  return 'Reactive — only call if covenant trips';
        return 'Silent — no bank conversation';
    }
}

